import { NextResponse } from 'next/server';
import ytdl from '@distube/ytdl-core';

// Forzar entorno Node.js para que funcionen los streams
export const runtime = 'nodejs';

// Lista de instancias públicas de Cobalt
const COBALT_INSTANCES = [
  "https://api.cobalt.tools", // Oficial (v10)
  "https://cobalt.wuk.sh",    // Muy estable (v10)
  "https://cobalt.kwiatekmiki.com",
  "https://cobalt-api.kwiatekmiki.com"
];

export async function POST(req: Request) {
  let url = '';
  
  try {
    const body = await req.json();
    url = body.url;

    if (!url) return NextResponse.json({ error: 'Falta URL' }, { status: 400 });

    console.log(`[Hybrid Downloader] Iniciando para: ${url}`);

    // --- ESTRATEGIA 1: COBALT API (v10 y v7) ---
    for (const instance of COBALT_INSTANCES) {
      try {
        console.log(`[Hybrid] Probando instancia: ${instance}`);
        
        // Configuración para Cobalt
        const headers = { 
            'Accept': 'application/json', 
            'Content-Type': 'application/json',
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
        };
        
        const bodyPayload = JSON.stringify({
            url: url,
            videoQuality: "720",
            filenamePattern: "basic"
        });

        // Intentar endpoint v10 (Raíz)
        let response = await fetch(`${instance}/`, { method: 'POST', headers, body: bodyPayload });
        
        // Si falla (404), intentar endpoint v7 (/api/json)
        if (response.status === 404) {
             response = await fetch(`${instance}/api/json`, { method: 'POST', headers, body: bodyPayload });
        }

        if (!response.ok) continue; // Probar siguiente instancia

        const data = await response.json();
        
        // Verificar si nos dio una URL válida (v10 o v7)
        const tunnelUrl = data.url || data.picker?.[0]?.url;

        if (tunnelUrl) {
            console.log(`[Hybrid] ¡Éxito con Cobalt! URL: ${tunnelUrl}`);
            
            // Descargar el archivo desde el túnel
            const fileRes = await fetch(tunnelUrl);
            if (!fileRes.ok) throw new Error("Error bajando del túnel");

            // Devolver stream al cliente
            const responseHeaders = new Headers();
            responseHeaders.set('Content-Type', 'video/mp4');
            responseHeaders.set('Content-Disposition', 'attachment; filename="video.mp4"');
            
            return new NextResponse(fileRes.body, { status: 200, headers: responseHeaders });
        }
      } catch (e) {
        // Silencioso, probar siguiente
      }
    }

    console.log("[Hybrid] Cobalt falló. Intentando motor local (ytdl-core)...");

    // --- ESTRATEGIA 2: MOTOR LOCAL (ytdl-core) ---
    // Esto funciona si Cobalt falla, usando tu propio servidor.
    if (!ytdl.validateURL(url)) {
        throw new Error("URL no válida para motor local");
    }

    const info = await ytdl.getInfo(url);
    const videoStream = ytdl(url, { 
        quality: 'highest', 
        filter: format => format.container === 'mp4' && format.hasAudio && format.hasVideo 
    });

    const localHeaders = new Headers();
    localHeaders.set('Content-Type', 'video/mp4');
    localHeaders.set('Content-Disposition', `attachment; filename="video.mp4"`);

    // @ts-ignore: Tipos de next stream
    return new NextResponse(videoStream, { status: 200, headers: localHeaders });

  } catch (error: any) {
    console.error("[Hybrid Error]:", error);
    return NextResponse.json({ 
        error: "No se pudo descargar el video con ningún método. Es posible que YouTube esté bloqueando la IP del servidor." 
    }, { status: 500 });
  }
}